  "whatsNew.replicaTakeOver": "โฟลเดอร์เรพลิกา ZFS ที่ BombVault ตัวนี้เคยใช้ก่อนตั้งค่าใหม่ รับมาเป็นของตนได้แล้ว และเรพลิกาถัดไปจะทำต่อจากสำเนาในโฟลเดอร์นั้น",
