  "whatsNew.startOver": "ตำแหน่งจัดเก็บระยะไกลที่ที่เก็บข้อมูลหายไปจะไม่ได้ที่เก็บข้อมูลใหม่ที่ว่างเปล่าเอง หน้าของตำแหน่งนั้นจะบอกและเสนอให้สร้างที่เก็บข้อมูลใหม่ตรงนั้น",
  "whatsNew.keyInstall": "ตอนตั้งค่า Storage Box หรือเซิร์ฟเวอร์ SFTP สามารถวางคีย์ SSH ของ BombVault ไว้ที่นั่นด้วยรหัสผ่านของบัญชี ซึ่งใช้ครั้งเดียวและไม่ถูกเก็บไว้ที่ใด และมีคำสั่งสำหรับทำเองแสดงอยู่ด้านล่าง",
  "whatsNew.instancesCardLogo": "การ์ดอินสแตนซ์ทุกใบแสดงโลโก้ที่ตำแหน่งเดียวกันและขนาดเดียวกัน ในระดับเดียวกับชื่อ",
