  "whatsNew.instancesFullNames": "การ์ดอินสแตนซ์แสดงชื่อเต็ม ป้ายจะย้ายไปอยู่ใต้ชื่อที่ยาว และประเภทของอินสแตนซ์มีบรรทัดของตัวเอง",
  "whatsNew.instancesNetLabels": "ชื่อในภาพของกลุ่มจะขึ้นบรรทัดใหม่แทนที่จะถูกตัด",
