  "oauth.reads": "จะอ่านสถานะการสำรองข้อมูลได้ ได้แก่ อะไรได้รับการป้องกัน แต่ละรายการสำรองครั้งล่าสุดเมื่อไร การรันแต่ละครั้งเป็นอย่างไร และบันทึกของการรันเขียนว่าอะไร การกู้คืน การลบ และการตั้งค่ายังอยู่ในเว็บอินเทอร์เฟซนี้",
