  "oauth.startedHere": "อนุญาตเฉพาะเมื่อคุณเพิ่งเริ่มการลงชื่อเข้าใช้นี้ด้วยตัวเองเมื่อครู่ ลิงก์ที่คนอื่นส่งมาอาจเชื่อมบัญชี {name} ของเขาเข้ากับ BombVault ของคุณ",
  "oauth.loopback": "ไคลเอนต์นี้กลับไปยังโปรแกรมบนคอมพิวเตอร์ของคุณเอง และโปรแกรมใดก็ได้ในเครื่องนั้นอาจแอบอ้างเป็นไคลเอนต์นี้ได้ อนุญาตเฉพาะเมื่อคุณเพิ่งเริ่มการลงชื่อเข้าใช้นี้ด้วยตัวเองเมื่อครู่",
  "oauth.allowStartHint": "เมื่อเปิดตัวเลือกนี้ ไคลเอนต์จะเริ่มการสำรองข้อมูลและยกเลิกรายการที่ตัวเองเริ่มได้ด้วย โดยมีขีดจำกัดเดียวกับคีย์ การสำรองข้อมูลจะหยุดคอนเทนเนอร์ที่กำลังทำงานจนกว่าจะเสร็จ คุณเปลี่ยนเรื่องนี้ภายหลังได้ที่ไทล์ของไคลเอนต์ใน การตั้งค่า, การเชื่อมต่อ, เซิร์ฟเวอร์ MCP",
